1 | /**
2 |  * 主入口文件
3 |  * 初始化并启动 AI Agent 应用
4 |  */
5 | import dotenv from 'dotenv';
6 | import { OpenAIProvider } from './providers/openai';
7 | import Agent from './agent';
8 | import { connectDB } from './storage/mongoose';
9 | import { CLI } from './cli';
10 | import { registerDefaultToolsAsync, ToolRegistry } from './tool';
11 | import { SessionManager } from './session-v2';
12 | import { operatorPrompt } from './prompts/operator';
13 | import path from 'path';
14 | import fs from 'fs';
15 | 
16 | const env = process.env.NODE_ENV || 'development';
17 | dotenv.config({ path: `.env.${env}`, override: true });
18 | 
19 | /**
20 |  * 应用配置
21 |  */
22 | interface AppConfig {
23 |     deepseekApiKey: string;
24 |     deepseekBaseUrl: string;
25 | }
26 | 
27 | /**
28 |  * 初始化应用
29 |  */
30 | async function initializeApp(config: AppConfig) {
31 |     // 1. 连接数据库
32 |     // await connectDB();
33 | 
34 |     // 2. 初始化工具（包括 MCP 工具）
35 |     await registerDefaultToolsAsync();
36 | 
37 |  
38 |     // 5. 初始化 LLM Provider
39 |     const llmProvider = new OpenAIProvider({
40 |         apiKey: config.deepseekApiKey,
41 |         baseURL: config.deepseekBaseUrl,
42 |     });
43 |       
44 | 
45 |    const sessionManager = new SessionManager({
46 |        sessionId:new Date().getTime().toString(),
47 |        llmProvider,
48 |    });
49 |    
50 |   await sessionManager.init();
51 | 
52 |     ToolRegistry.setContext({
53 |         sessionId: sessionManager.id,
54 |         sessionPath: sessionManager.sessionPath,
55 |     });
56 | 
57 |     const tools = ToolRegistry.getSchemas();
58 | 
59 |     const customPrompt = operatorPrompt({
60 |         directory: process.cwd(),
61 |         vcs: "git",
62 |         tools,
63 |     });
64 |     fs.writeFileSync(path.resolve(process.cwd(), 'customPrompt.md'), customPrompt);
65 |     const agent = new Agent({
66 |         llmProvider,
67 |         sessionManager,
68 |         systemPrompt: customPrompt,
69 |         defaultTools: tools,
70 |     });
71 | 
72 |     return { agent, sessionManager };
73 | }
74 | 
75 | /**
76 |  * 启动 CLI 交互模式
77 |  */
78 | async function startCLI(agent: Agent, sessionManager: SessionManager): Promise<void> {
79 |     const cli = new CLI({
80 |         agent,
81 |         sessionManager,
82 |         sessionId: sessionManager.id,
83 |         prompt: '>',
84 |     });
85 | 
86 |     await cli.start();
87 | }
88 | 
89 | 
90 | /**
91 |  * 主函数
92 |  */
93 | async function main() {
94 |     // 验证环境变量
95 |     const deepseekApiKey = process.env.DEEPSEEK_API_KEY;
96 |     const deepseekBaseUrl = process.env.DEEPSEEK_BASE_URL;
97 | 
98 |     if (!deepseekApiKey) {
99 |         throw new Error('DEEPSEEK_API_KEY is not set');
100 |     }
101 | 
102 |     if (!deepseekBaseUrl) {
103 |         throw new Error('DEEPSEEK_BASE_URL is not set');
104 |     }
105 | 
106 |     // 初始化应用
107 |     const { agent, sessionManager } = await initializeApp({
108 |         deepseekApiKey,
109 |         deepseekBaseUrl,
110 |     });
111 | 
112 |     // 检查命令行参数
113 |     const args = process.argv.slice(2);
114 |     const mode = args[0] || 'cli';
115 | 
116 |     switch (mode) {
117 |         case 'cli':
118 |         default:
119 |             await startCLI(agent, sessionManager);
120 |             break;
121 |     }
122 | }
123 | 
124 | main().catch(console.error);
125 |

--- FILE: src/agent/index.ts ---
Range: 1 - 382

1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  * 
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, ToolSchema } from "../providers/base";
10 | import { ScopedLogger } from "../util/log";
11 | import { formatToolResult } from "../util/log-format";
12 | import { SessionManager } from "../session-v2";
13 | import { SYSTEM_PROMPT } from "../prompts/system";
14 | import { ToolRegistry } from "../tool/registry";
15 | 
16 | export interface AgentConfig {
17 |     llmProvider: LLMProvider;
18 |     sessionManager: SessionManager;
19 |     systemPrompt: string;
20 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
21 |     defaultTools?: ToolSchema[];
22 |     /** 最大循环次数，防止无限循环，默认 10 */
23 |     maxLoop?: number;
24 |     /** 最大 token 数，默认 8000 */
25 |     maxTokens?: number;
26 |     /** 最大输出 token 数，默认 8000 */
27 |     maxOutputTokens?: number;
28 |     /** 工具并发上限，默认 4 */
29 |     toolConcurrency?: number;
30 |     /** 单次工具调用超时（毫秒），默认 120000 */
31 |     toolTimeoutMs?: number;
32 |     /** 连续重复的工具调用轮次上限，默认 2 */
33 |     noProgressLimit?: number;
34 | }
35 | 
36 | export interface AgentResponse {
37 |     content: string;
38 |     role: 'assistant';
39 | }
40 | 
41 | export default class Agent extends EventEmitter {
42 |     private llmProvider: LLMProvider;
43 |     private logger: ScopedLogger;
44 |     private sessionManager: SessionManager;
45 |     private systemPrompt: string;
46 |     private defaultTools: ToolSchema[] | undefined;
47 |     private maxLoop: number;
48 |     maxOutputTokens: number;
49 |     maxTokens: number;
50 |     private toolConcurrency: number;
51 |     private toolTimeoutMs: number;
52 |     private noProgressLimit: number;
53 |     constructor(config: AgentConfig) {
54 |         super();
55 |         this.llmProvider = config.llmProvider;
56 |         this.sessionManager = config.sessionManager;
57 |         this.systemPrompt = config.systemPrompt;
58 |         this.defaultTools = config.defaultTools;
59 |         this.logger = new ScopedLogger('Agent');
60 |         this.maxLoop = config.maxLoop ?? 1024;
61 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
62 |         const providerMaxTokens = this.llmProvider.maxTokens;
63 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
64 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
65 |         this.toolConcurrency = Math.max(1, config.toolConcurrency ?? 4);
66 |         this.toolTimeoutMs = config.toolTimeoutMs ?? 120000;
67 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
68 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
69 |         this.sessionManager.maxTokens = this.maxTokens;
70 |     }
71 | 
72 |     private async withTimeout<T>(promise: Promise<T>, timeoutMs: number, timeoutMessage: string): Promise<T> {
73 |         if (!timeoutMs || timeoutMs <= 0) {
74 |             return promise;
75 |         }
76 | 
77 |         let timeoutId: ReturnType<typeof setTimeout> | undefined;
78 |         const timeoutPromise = new Promise<never>((_, reject) => {
79 |             timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
80 |         });
81 | 
82 |         return Promise.race([promise, timeoutPromise]).finally(() => {
83 |             if (timeoutId) {
84 |                 clearTimeout(timeoutId);
85 |             }
86 |         });
87 |     }
88 | 
89 |     private async runWithConcurrency<T, R>(
90 |         items: T[],
91 |         limit: number,
92 |         task: (item: T, index: number) => Promise<R>
93 |     ): Promise<R[]> {
94 |         if (items.length === 0) {
95 |             return [];
96 |         }
97 | 
98 |         if (limit <= 1) {
99 |             const results: R[] = [];
100 |             for (let i = 0; i < items.length; i++) {
101 |                 results.push(await task(items[i], i));
102 |             }
103 |             return results;
104 |         }
105 | 
106 |         const results = new Array<R>(items.length);
107 |         let nextIndex = 0;
108 |         const workerCount = Math.min(limit, items.length);
109 | 
110 |         const workers = Array.from({ length: workerCount }, async () => {
111 |             while (true) {
112 |                 const currentIndex = nextIndex++;
113 |                 if (currentIndex >= items.length) {
114 |                     break;
115 |                 }
116 |                 results[currentIndex] = await task(items[currentIndex], currentIndex);
117 |             }
118 |         });
119 | 
120 |         await Promise.all(workers);
121 |         return results;
122 |     }
123 | 
124 |     private buildToolSignature(toolCalls: NonNullable<LLMResponse['tool_calls']>): string {
125 |         try {
126 |             return JSON.stringify(
127 |                 toolCalls.map((call) => ({
128 |                     name: call.function.name,
129 |                     arguments: call.function.arguments,
130 |                 }))
131 |             );
132 |         } catch (_) {
133 |             return '';
134 |         }
135 |     }
136 | 
137 |     /**
138 |      * 运行 Agent 处理用户查询
139 |      * @param sessionId 会话 ID
140 |      * @param userId 用户 ID
141 |      * @param query 用户查询
142 |      * @param options 选项
143 |      * @returns Agent 响应
144 |      */
145 |     async run(
146 |         query: string,
147 |         options?: { silent?: boolean; tools?: ToolSchema[] }
148 |     ): Promise<AgentResponse | null> {
149 | 
150 |      
151 |         try {
152 | 
153 |             // 3. 获取工具 schemas（优先级：传入参数 > 默认配置 > ToolRegistry 全部）
154 |             const tools = options?.tools ?? this.defaultTools ?? [];
155 | 
156 |             // 4. LLM 调用循环（处理工具调用）
157 |             let i = 0; // 防止无限循环
158 |             let finalResponse: AgentResponse | null = null;
159 |             let lastToolSignature: string | null = null;
160 |             let repeatedToolCalls = 0;
161 |   
162 |   
163 |             this.sessionManager.addMessage({
164 |                 role: 'user',
165 |                 type: 'text',
166 |                 content: query
167 |             });
168 | 
169 |             while (i < this.maxLoop) {
170 |                 i++; // 在循环开始时递增计数器
171 | 
172 |                 const llmMessages = await this.sessionManager.getMessages();
173 | 
174 |                 const spinner = this.logger.spinner(`Thinking-${i}...`);
175 |                 let llmResponse: Awaited<ReturnType<LLMProvider['generate']>> = null;
176 |                 try {
177 |                     // 调用 LLM
178 |                     llmResponse = await this.llmProvider.generate([
179 |                         {
180 |                             role: 'system',
181 |                             content: this.systemPrompt,
182 |                         },
183 |                         ...llmMessages
184 |                     ], {
185 |                         model: process.env.AI_MODEL,
186 |                         tools: tools.length > 0 ? tools : undefined,
187 |                         max_tokens: this.maxOutputTokens,
188 |                     });
189 |                     // console.log( this.systemPrompt)
190 |                 } catch (error) {
191 |                     const errorMsg = error instanceof Error ? error.message : String(error);
192 | 
193 |                     spinner.fail(`Thinking-${i} failed`);
194 | 
195 |                     this.logger.error(`LLM error: ${errorMsg}`);
196 |                       this.sessionManager.addMessage({
197 |                         role: 'assistant',
198 |                         type: 'text',
199 |                         content: errorMsg
200 |                     });
201 | 
202 |                     return {
203 |                         content: errorMsg,
204 |                         role: 'assistant',
205 |                     };
206 |                 }
207 | 
208 |                 if (!llmResponse) {
209 |                     const errorMsg = 'LLM returned null response';
210 |                     this.logger.error(errorMsg);
211 |                     spinner.fail(`Thinking-${i} failed`);
212 | 
213 |                    this.sessionManager.addMessage({
214 |                         role: 'assistant',
215 |                         type: 'text',
216 |                         content: errorMsg
217 |                     });
218 | 
219 |                     return {
220 |                         content: errorMsg,
221 |                         role: 'assistant',
222 |                     };
223 |                 }
224 |                 spinner.succeed(`Thinking-${i} end`);
225 | 
226 |                 // 检查是否有工具调用
227 |                 if (llmResponse.tool_calls && llmResponse.tool_calls.length > 0) {
228 |                     const toolSignature = this.buildToolSignature(llmResponse.tool_calls);
229 |                     if (toolSignature && toolSignature === lastToolSignature) {
230 |                         repeatedToolCalls += 1;
231 |                     } else {
232 |                         repeatedToolCalls = 0;
233 |                         lastToolSignature = toolSignature;
234 |                     }
235 | 
236 |                     if (this.noProgressLimit > 0 && repeatedToolCalls >= this.noProgressLimit) {
237 |                         const errorMsg = `Repeated tool_calls detected for ${this.noProgressLimit + 1} iterations, aborting to prevent loop.`;
238 |                         this.logger.error(errorMsg);
239 |                         this.sessionManager.addMessage({
240 |                                 role: 'assistant',
241 |                                 type: 'text',
242 |                                 content: errorMsg
243 |                          });
244 | 
245 |                         return {
246 |                             content: errorMsg,
247 |                             role: 'assistant',
248 |                         };
249 |                     }
250 | 
251 |                     // 添加 assistant 消息（包含 tool_calls）
252 |                     this.sessionManager.addMessage({
253 |                         role: 'assistant',
254 |                         content: llmResponse.content,
255 |                         type: 'tool_call',
256 |                         tool_calls: llmResponse.tool_calls,
257 |                     });
258 | 
259 |                     this.logger.info(`Tool tips: ${llmResponse.content}`);
260 | 
261 |                     const toolCalls = llmResponse.tool_calls;
262 |                     const toolConcurrency = Math.min(this.toolConcurrency, toolCalls.length);
263 | 
264 |                     const results = await this.runWithConcurrency(toolCalls, toolConcurrency, async (toolCall) => {
265 |                         const { id,function: fn } = toolCall;
266 |                         try {
267 |                             // 解析参数（带容错处理）
268 |                             let args: unknown;
269 |                             try {
270 |                                 args = JSON.parse(fn.arguments);
271 |                             } catch (parseError) {
272 |                                 // JSON 解析失败 - 记录详细信息并返回友好的错误信息
273 |                                 const truncatedArgs = fn.arguments.length > 200
274 |                                     ? fn.arguments.slice(0, 200) + '...'
275 |                                     : fn.arguments;
276 |                                 const parseErrorMsg = parseError instanceof Error ? parseError.message : String(parseError);
277 |                                 const errorMsg = `Invalid JSON in tool parameters: ${parseErrorMsg}\nReceived: ${truncatedArgs}`;
278 |                                 this.logger.error(errorMsg);
279 |                                 return {
280 |                                     toolCall,
281 |                                     result: `Error: Failed to parse tool arguments. The JSON was malformed. Please try again with properly formatted parameters.`,
282 |                                     error: errorMsg,
283 |                                     id,
284 |                                 };
285 |                             }
286 | 
287 |                             const spinner = this.logger.spinner(`Tool ${fn.name}(...)`);
288 |                             // 执行工具
289 |                             let result: string;
290 |                             try {
291 |                                 result = await this.withTimeout(
292 |                                     ToolRegistry.execute(fn.name, args),
293 |                                     this.toolTimeoutMs,
294 |                                     `Tool ${fn.name} timed out after ${this.toolTimeoutMs}ms`
295 |                                 );
296 |                                 spinner.succeed(`Tool ${fn.name} completed`);
297 |                             } catch (error) {
298 |                                 spinner.fail(`Tool ${fn.name} failed`);
299 |                                 throw error;
300 |                             }
301 | 
302 |                             if (!options?.silent) {
303 |                                 this.logger.info(`Tool ${fn.name} result: ${formatToolResult(fn.name, result)}`);
304 |                             }
305 | 
306 |                             // 返回成功结果
307 |                             return { toolCall, result, error: undefined ,id};
308 |                         } catch (error) {
309 |                             const errorMsg = error instanceof Error ? error.message : String(error);
310 |                             this.logger.error(`Tool execution error: ${errorMsg}`);
311 | 
312 |                             // 返回错误结果
313 |                             return { toolCall, result: `Error: ${errorMsg}`, error: errorMsg,id };
314 |                         }
315 |                     });
316 | 
317 |                     // 按原始顺序添加工具结果消息
318 |                     for (const { toolCall, result, error: _error } of results) {
319 |                         const { id } = toolCall;
320 | 
321 |                         this.sessionManager.addMessage({
322 |                             role: 'tool',
323 |                             content: result,
324 |                             type: 'tool',
325 |                             tool_call_id: id,
326 |                         });
327 |                     }
328 | 
329 |                     // 继续循环，让 LLM 基于工具结果生成响应
330 |                     continue;
331 |                 }
332 | 
333 |                 // 没有工具调用，这是最终响应
334 |                 this.sessionManager.addMessage({
335 |                     role: 'assistant',
336 |                     type: 'text',
337 |                     content: llmResponse.content,
338 |                 });
339 | 
340 |                 finalResponse = {
341 |                     content: llmResponse.content,
342 |                     role: 'assistant',
343 |                 };
344 | 
345 |                 break;
346 |             }
347 | 
348 |             if (i >= this.maxLoop) {
349 |                 this.logger.error('Max iterations reached, possible infinite loop');
350 |                 this.sessionManager.addMessage({
351 |                         role: 'assistant',
352 |                         type: 'text',
353 |                         content: 'Max iterations reached, possible infinite loop'
354 |                  });
355 | 
356 |                 return {
357 |                     content: 'Max iterations reached, possible infinite loop',
358 |                     role: 'assistant',
359 |                 };
360 |             }
361 | 
362 |     
363 | 
364 |             return finalResponse;
365 | 
366 |         } catch (error) {
367 |             const errorMsg = error instanceof Error ? error.message : String(error);
368 |             this.logger.error(`Agent error: ${errorMsg}`);
369 |              this.sessionManager.addMessage({
370 |                         role: 'assistant',
371 |                         type: 'text',
372 |                         content: errorMsg
373 |            });
374 |             return {
375 |                 content: errorMsg,
376 |                 role: 'assistant',
377 |             };
378 |         }
379 |     }
380 | 
381 | }
382 |

--- FILE: src/session-v2/index.ts ---
Range: 1 - 113

1 | import path from "node:path";
2 | import { LLMProvider, Message } from "../providers/base";
3 | import fs, { mkdir } from 'node:fs/promises';
4 | import { Compaction } from "./compaction";
5 | 
6 | export class SessionManager {
7 |   id: string;
8 |   messageList: Message[];
9 |   sessionPath: string;
10 |   private saveQueue: Promise<void> = Promise.resolve();
11 |   maxOutputTokens: number;
12 |   maxTokens: number;
13 |   llmProvider: LLMProvider;
14 | 
15 |   constructor({
16 |     sessionId,
17 |     llmProvider
18 |   }: {
19 |     sessionId: string,
20 |     llmProvider: LLMProvider
21 |   }) {
22 |     this.id = sessionId;
23 |     this.messageList = []
24 |     this.sessionPath = path.join('.memory', this.id);
25 |     this.maxOutputTokens = llmProvider.maxOutputTokens;
26 |     this.maxTokens = llmProvider.maxTokens
27 |     this.llmProvider = llmProvider;
28 |   }
29 | 
30 |   async init() {
31 |     await mkdir(this.sessionPath, { recursive: true });
32 |     try {
33 |       const filePath = path.join(this.sessionPath, 'messages.json');
34 |       const stats = await fs.stat(filePath);
35 | 
36 |       if (stats.isFile()) {
37 |         const content = await fs.readFile(filePath, {
38 |           encoding: 'utf-8'
39 |         });
40 | 
41 |         const messageList = JSON.parse(content.trim());
42 |         if (messageList.length) {
43 |           this.messageList = messageList;
44 |         }
45 |       }
46 |     } catch (_:any) {
47 |       // 文件不存在或其他错误，忽略
48 |       console.log("NOT FOUND HISTORY")
49 |     }
50 |   }
51 | 
52 |   addMessage(message: Message) {
53 |     this.messageList.push(message);
54 |     // Fire-and-forget：加入保存队列，不阻塞调用方
55 |     this.save(message);
56 |   }
57 | 
58 |   async compact() {
59 |     const compaction = new Compaction({
60 |       maxOutputTokens: this.maxOutputTokens,
61 |       maxTokens: this.maxTokens,
62 |       llmProvider: this.llmProvider
63 |     });
64 | 
65 |     const token = compaction.getToken(this.messageList);
66 |     console.log(`TOKEN: ${token.totalUsed}/${token.usableLimit}\n`);
67 |     
68 |     return await compaction.compact(this.messageList);
69 |   }
70 | 
71 |   private save(message: Message) {
72 |     // 使用 Promise 链确保保存顺序，防止竞态条件
73 |     this.saveQueue = this.saveQueue.then(async () => {
74 |       try {
75 |         await fs.writeFile(
76 |           path.join(this.sessionPath, 'messages.json'),
77 |           JSON.stringify(this.messageList, null, 2)
78 |         );
79 |         await fs.appendFile(
80 |           path.join(this.sessionPath, 'cache.md'),
81 |           `\`\`\`\n${JSON.stringify(message, null, 2)}\n\`\`\`\n`,
82 |           { flag: 'a' }
83 |         );
84 |       } catch (err) {
85 |         console.error('Session save error:', err);
86 |       }
87 |     });
88 |   }
89 | 
90 |   async getMessages(): Promise<Message[]> {
91 |     // if (this.messageList.length < 10) {
92 |     //   return this.messageList;
93 |     // }
94 | 
95 |     const result = await this.compact();
96 | 
97 |     this.messageList = result.list;
98 | 
99 |     if (result.isCompacted && result.summaryMessage) {
100 |       this.save(result.summaryMessage)
101 |     }
102 | 
103 |     return this.messageList
104 |   }
105 | 
106 |   async clearAll() {
107 |     this.messageList = [];
108 |     await fs.writeFile(
109 |       path.join(this.sessionPath, 'messages.json'),
110 |       '[]'
111 |     );
112 |   }
113 | }

--- FILE: src/tool/index.ts ---
Range: 1 - 132

1 | /**
2 |  * Tool Registry
3 |  *
4 |  * 工具注册中心，负责管理所有可用的工具
5 |  *
6 |  * @example
7 |  * ```ts
8 |  * import { ToolRegistry } from './index';
9 |  *
10 |  * // 获取所有工具
11 |  * const tools = ToolRegistry.getAll();
12 |  *
13 |  * // 根据名称获取工具
14 |  * const bashTool = ToolRegistry.get('bash');
15 |  *
16 |  * // 执行工具
17 |  * const result = await bashTool.execute({ command: 'ls' });
18 |  * ```
19 |  */
20 | 
21 | import { ToolRegistry } from './registry';
22 | import BashTool from './bash';
23 | import GlobTool from './glob';
24 | import { ReadFileTool } from './file';
25 | import { WriteFileTool } from './file';
26 | import GrepTool from './grep';
27 | import { SurgicalEditTool } from './surgical';
28 | import { BatchReplaceTool } from './batch-replace';
29 | import { TodoReadTool } from './todo';
30 | import { TodoWriteTool } from './todo';
31 | import { initializeMcp } from '../mcp/index';
32 | import { WebSearchTool } from './web-search';
33 | import { SkillTool, initializeSkills } from '../skills';
34 | import TaskTool from './task';
35 | 
36 | // =============================================================================
37 | // Tool Registry
38 | // =============================================================================
39 | 
40 | export { ToolRegistry } from './registry';
41 | 
42 | // =============================================================================
43 | // Default Tools Registration
44 | // =============================================================================
45 | 
46 | /**
47 |  * 初始化并注册所有默认工具
48 |  *
49 |  * 在应用启动时调用此函数
50 |  */
51 | export function registerDefaultTools(): void {
52 | 
53 |     ToolRegistry.register([
