11 | /**
12 |  * 修复 LLM 生成的格式错误的 JSON
13 |  *
14 |  * DeepSeek 等 LLM 在生成工具调用参数时，有时会生成格式错误的 JSON。
15 |  * 最常见的问题是：
16 |  * 1. 字符串值中包含未转义的换行符
17 |  * 2. 响应被截断（token 限制），导致 JSON 不完整
18 |  *
19 |  * 此函数尝试修复这些常见问题。
20 |  */
21 | function fixMalformedJson(potentiallyMalformedJson: string): string {
22 |   const originalError: { message: string; attempt?: number }[] = [];
23 | 
24 |   // 如果 JSON 本身是有效的，直接返回
25 |   try {
26 |     JSON.parse(potentiallyMalformedJson);
27 |     return potentiallyMalformedJson;
28 |   } catch (e) {
29 |     originalError.push({ message: e instanceof Error ? e.message : String(e) });
30 |   }
31 | 
32 |   let fixed = potentiallyMalformedJson;
33 | 
34 |   // 尝试 1: 修复截断的 JSON（未闭合的字符串）
35 |   const fixed1 = fixTruncatedJson(fixed);
36 |   if (fixed1 !== fixed) {
37 |     try {
38 |       JSON.parse(fixed1);
39 |       return fixed1;
40 |     } catch (e) {
41 |       originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 1 });
42 |     }
43 |     fixed = fixed1;
44 |   }
45 | 
46 |   // 尝试 2: 处理 JSON 字符串值中的未转义换行符
47 |   // 这是最常见的问题：LLM 在生成字符串值时直接包含换行而不是 \n
48 |   if (!fixed.includes('\\n')) {
49 |     // 只有在没有转义换行符的情况下才尝试这个修复
50 |     // 如果已经有 \n，说明 JSON 可能是正确的，只是有其他问题
51 |     const fixed2 = fixUnescapedNewlinesInStrings(fixed);
52 |     try {
53 |       JSON.parse(fixed2);
54 |       return fixed2;
55 |     } catch (e) {
56 |       originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 2 });
57 |     }
58 |     fixed = fixed2;
59 |   }
60 | 
61 |   // 尝试 3: 去除所有控制字符并替换为转义序列
62 |   const fixed3 = fixed.replace(/[\x00-\x08\x0B-\x0C\x0E-\x1F\x7F]/g, '');
63 |   try {
64 |     JSON.parse(fixed3);
65 |     return fixed3;
66 |   } catch (e) {
67 |     originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 3 });
68 |   }
69 | 
70 |   // 尝试 4: 尝试闭合未完成的 JSON 结构
71 |   const fixed4 = attemptToCloseJson(fixed);
72 |   try {
73 |     JSON.parse(fixed4);
74 |     return fixed4;
75 |   } catch (e) {
76 |     originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 4 });
77 |   }
78 | 
79 |   // 所有尝试都失败，抛出原始错误
80 |   throw new Error(`Failed to fix malformed JSON. Original errors: ${JSON.stringify(originalError)}`);
81 | }
