150 | /**
151 |  * 尝试通过智能闭合来修复 JSON
152 |  */
153 | function attemptToCloseJson(json: string): string {
154 |   let result = json.trim();
155 | 
156 |   // 移除末尾可能的未完成部分
157 |   // 如果最后一个字符是逗号，移除它
158 |   if (result.endsWith(',')) {
159 |     result = result.slice(0, -1);
160 |   }
161 | 
162 |   // 统计括号
163 |   const counts = countBraces(result);
164 | 
165 |   // 如果缺少闭合引号，添加
166 |   if (counts.openQuotes % 2 !== 0) {
167 |     result = result + '"';
168 |   }
169 | 
170 |   // 闭合括号
171 |   for (let i = 0; i < counts.openBraces - counts.closeBraces; i++) {
172 |     result = result + '}';
173 |   }
174 |   for (let i = 0; i < counts.openBrackets - counts.closeBrackets; i++) {
175 |     result = result + ']';
176 |   }
177 | 
178 |   return result;
179 | }
