181 | /**
182 |  * 统计 JSON 中的括号和引号
183 |  */
184 | function countBraces(json: string) {
185 |   const counts = {
186 |     openBraces: 0,
187 |     closeBraces: 0,
188 |     openBrackets: 0,
189 |     closeBrackets: 0,
190 |     openQuotes: 0,
191 |   };
192 | 
193 |   let inString = false;
194 |   let escapeNext = false;
195 | 
196 |   for (const char of json) {
197 |     if (escapeNext) {
198 |       escapeNext = false;
199 |       continue;
200 |     }
201 | 
202 |     if (char === '\\') {
203 |       escapeNext = true;
204 |       continue;
205 |     }
206 | 
207 |     if (char === '"') {
208 |       if (!inString) {
209 |         counts.openQuotes++;
210 |         inString = true;
211 |       } else {
212 |         counts.openQuotes++; // 计数，不区分开闭
213 |         inString = false;
214 |       }
215 |       continue;
216 |     }
217 | 
218 |     if (!inString) {
219 |       if (char === '{') counts.openBraces++;
220 |       if (char === '}') counts.closeBraces++;
221 |       if (char === '[') counts.openBrackets++;
222 |       if (char === ']') counts.closeBrackets++;
223 |     }
224 |   }
225 | 
226 |   return counts;
227 | }
