229 | /**
230 |  * 修复 JSON 字符串值中未转义的换行符
231 |  *
232 |  * 通过解析 JSON 结构，找到所有字符串值，并转义其中的特殊字符。
233 |  */
234 | function fixUnescapedNewlinesInStrings(json: string): string {
235 |   // 这是一个简化的实现，处理最常见的模式
236 |   // 模式: "key": "value with
237 |   // actual newline"
238 | 
239 |   const lines = json.split('\n');
240 |   const result: string[] = [];
241 |   let inString = false;
242 |   let escapeNext = false;
243 | 
244 |   for (let i = 0; i < lines.length; i++) {
245 |     const line = lines[i];
246 | 
247 |     if (!inString) {
248 |       result.push(line);
249 |       // 检查这一行后是否进入字符串状态
250 |       for (const char of line) {
251 |         if (escapeNext) {
252 |           escapeNext = false;
253 |           continue;
254 |         }
255 |         if (char === '\\') {
256 |           escapeNext = true;
257 |           continue;
258 |         }
259 |         if (char === '"') {
260 |           inString = !inString;
261 |         }
262 |       }
263 |     } else {
264 |       // 在字符串中，添加转义的换行
265 |       result.push('\\n' + line.trim());
266 |       // 检查这一行后是否退出字符串状态
267 |       for (const char of line) {
268 |         if (escapeNext) {
269 |           escapeNext = false;
270 |           continue;
271 |         }
272 |         if (char === '\\') {
273 |           escapeNext = true;
274 |           continue;
275 |         }
276 |         if (char === '"') {
277 |           inString = !inString;
278 |         }
279 |       }
280 |     }
281 |   }
282 | 
283 |   return result.join('\n');
284 | }
