111 |     private tryHandleCd(command: string): string | null {
112 |         const platform = getPlatform();
113 |         // 检测复杂命令（包含管道、重定向、命令连接符等），不做 cd 特殊处理
114 |         if (/[|;&<>]|\|\||&&/.test(command)) {
