148 |         const { tokens, quoteTypes } = this.tokenize(command);
149 |         const normalizedTokens = tokens.map((token, i) => {
150 |             const quote = quoteTypes[i];
151 |             const original = quote ? `${quote}${token}${quote}` : token;
152 |             if (!token.includes('/')) return original;
153 |             if (token.startsWith('/')) return original;
154 |             if (token.includes('://')) return original;
155 | 
156 |             const looksLikeProjectPath =
157 |                 token.startsWith('./') ||
158 |                 token.startsWith('../') ||
159 |                 token.startsWith('src/') ||
160 |                 token.startsWith('test/') ||
161 |                 token.startsWith('__tests__/') ||
162 |                 /\.(ts|tsx|js|jsx|json|md|txt|log|env)$/i.test(token) ||
163 |                 token.includes('/src/') ||
164 |                 token.includes('/test/') ||
165 |                 token.includes('/__tests__/');
166 | 
167 |             if (!looksLikeProjectPath) return original;
168 | 
169 |             const replaced = token.replace(/\//g, '\\');
170 |             return quote ? `${quote}${replaced}${quote}` : replaced;
171 |         });
