636 |             const toolSchemas = this.normalizeToolSchemas(this.resolveTools(options));
637 |             const toolStats: ToolStats = { calls: 0, duration: 0 };
638 | 
639 |             await this.recordMessage({
640 |                 role: 'user',
641 |                 type: 'text',
642 |                 content: query,
643 |             });
644 | 
