650 |             while (i < this.maxLoop) {
651 |                 i++;
652 | 
653 |                 // 触发循环迭代前钩子
654 |                 await this.triggerHook(AgentHook.BEFORE_LOOP_ITERATION, { iteration: i, maxLoop: this.maxLoop });
655 | 
656 |                 // 发布循环开始事件
657 |                 await this.eventBus.emit('agent.loop.start', { iteration: i, maxLoop: this.maxLoop });
658 | 
659 |                 // 获取会话消息
660 |                 const llmMessages = await this.sessionManager.getMessages();
661 | 
662 |                 // 发布消息获取事件
663 |                 await this.eventBus.emit('agent.messages.retrieved', {
664 |                     count: llmMessages.length,
665 |                     iteration: i,
666 |                 });
667 | 
668 |                 const { response: llmResponse } = await this.generateLLMResponse({
669 |                     query,
670 |                     llmMessages,
671 |                     toolSchemas,
672 |                     iteration: i,
673 |                     model,
674 |                 });
675 |                 if (!llmResponse) {
676 |                     return null;
677 |                 }
678 | 
679 |                 // 检查是否有工具调用
680 |                 if (llmResponse.tool_calls && llmResponse.tool_calls.length > 0) {
681 |                     const updatedProgress = await this.handleToolCalls({
682 |                         toolCalls: llmResponse.tool_calls,
683 |                         content: llmResponse.content,
684 |                         iteration: i,
685 |                         options,
686 |                         stats: toolStats,
687 |                         progress,
688 |                     });
689 |                     progress.lastToolSignature = updatedProgress.lastToolSignature;
690 |                     progress.repeatedToolCalls = updatedProgress.repeatedToolCalls;
691 | 
692 |                     // 继续循环
693 |                     continue;
694 |                 }
695 | 
696 |                 // 没有工具调用，这是最终响应
697 |                 await this.recordMessage({
698 |                     role: 'assistant',
699 |                     type: 'text',
700 |                     content: llmResponse.content,
701 |                 });
702 | 
703 |                 finalResponse = {
704 |                     content: llmResponse.content,
705 |                     role: 'assistant',
706 |                 };
707 | 
708 |                 // 发布 LLM 响应处理事件
709 |                 await this.eventBus.emit('agent.llm.response.processed', {
710 |                     content: llmResponse.content,
711 |                     hasToolCalls: false,
712 |                     iteration: i,
713 |                 });
714 | 
715 |                 // 发布循环完成事件
716 |                 await this.eventBus.emit('agent.loop.complete', {
717 |                     iteration: i,
718 |                     hasToolCalls: false,
719 |                 });
720 | 
721 |                 // 触发循环迭代后钩子
722 |                 await this.triggerHook(AgentHook.AFTER_LOOP_ITERATION, {
723 |                     iteration: i,
724 |                     hasToolCalls: false,
725 |                 });
726 | 
727 |                 break;
728 |             }
729 | 
730 |             if (i >= this.maxLoop) {
731 |                 // 发布最大循环达到事件
732 |                 await this.eventBus.emit('agent.loop.max.reached', {
733 |                     maxLoop: this.maxLoop,
734 |                     query,
735 |                 });
736 | 
737 |                 this.logger.error('Max iterations reached, possible infinite loop');
738 |                 return null;
739 |             }
740 | 
741 |             const totalDuration = Date.now() - startTime;
742 | 
743 |             // 发布性能指标事件
744 |             await this.eventBus.emit('agent.performance.metrics', {
745 |                 totalDuration,
746 |                 llmCalls: i,
747 |                 toolCalls: toolStats.calls,
748 |                 avgToolDuration: toolStats.calls > 0 ? toolStats.duration / toolStats.calls : 0,
749 |                 avgLLMDuration: totalDuration / i,
750 |                 iteration: i,
751 |             });
752 | 
753 |             // 触发性能指标钩子
754 |             await this.triggerHook(AgentHook.ON_PERFORMANCE_METRICS, {
755 |                 totalDuration,
756 |                 llmCalls: i,
757 |                 toolCalls: toolStats.calls,
758 |                 avgToolDuration: toolStats.calls > 0 ? toolStats.duration / toolStats.calls : 0,
759 |                 avgLLMDuration: totalDuration / i,
760 |                 iteration: i,
761 |             });
762 | 
763 |             // 发布运行完成事件
764 |             await this.eventBus.emit('agent.run.complete', {
765 |                 query,
766 |                 response: finalResponse?.content || null,
767 |                 duration: totalDuration,
768 |             });
769 | 
770 |             // 触发运行后钩子
771 |             await this.triggerHook(AgentHook.AFTER_RUN, {
772 |                 query,
773 |                 response: finalResponse,
