1 | import fs from 'fs';
2 | import path from 'path';
3 | import { isBinaryFile } from 'isbinaryfile';
4 | import { z } from 'zod';
5 | import { BaseTool } from './base';
6 | import { getBackupManager } from '../util/backup-manager';
7 | 
8 | 
9 | const readFileSchema = z.object({
10 |     filePath: z.string(),
11 |     startLine: z.number().optional().describe("The line number to start reading from (0-based)"),
12 |     endLine: z.number().optional().describe("The number of lines to read (defaults to 2000)")
13 | })
14 | 
15 | export class ReadFileTool extends BaseTool<typeof readFileSchema> {
16 |   name = "read_file";
17 |   description = `Read file content with line numbers.
18 | IMPORTANT USAGE GUIDELINES:
19 | - DEFAULT: Read the ENTIRE file by omitting startLine/endLine parameters
20 | - ONLY use range reading for files larger than 500 lines
21 | - If you need to read a file, ALWAYS try reading it completely first
22 | - The tool will return line numbers to help you navigate
23 | Most files are small enough to read entirely. Avoid premature optimization.`;
24 |   schema = readFileSchema;
25 | 
26 |   async execute(args: { filePath: string; startLine?: number; endLine?: number; }): Promise<string> {
27 |     const { filePath, startLine, endLine } = args;
28 |     const fullPath = path.resolve(process.cwd(), filePath);
29 |     if (!fs.existsSync(fullPath)) return "Error: File not found.";
30 |     if (await isBinaryFile(fullPath)) return "Error: Cannot read binary file.";
31 | 
32 |     const content = fs.readFileSync(fullPath, 'utf-8');
33 |     const lines = content.split('\n');
34 |     
35 |     const start = (startLine || 1) - 1;
36 |     const end = endLine || lines.length;
37 |     
38 |     const numbered = lines.slice(start, end).map((l, i) => `${start + i + 1} | ${l}`).join('\n');
39 |     
40 |     return `--- FILE: ${filePath} ---\nRange: ${start+1} - ${end}\n\n${numbered}`;
41 |   }
42 | }
43 | 
44 | const writeFileSchema = z.object({
45 |     filePath: z.string().describe("The absolute or relative path to the file"),
46 |     content: z.string().describe(
47 |         "The complete file content as a plain string. " +
48 |         "IMPORTANT: Provide the raw content directly, NOT wrapped in markdown code blocks or backticks. " +
49 |         "All newlines, quotes, and special characters will be properly handled automatically."
50 |     ),
51 | })
52 | 
53 | export class WriteFileTool extends BaseTool<typeof writeFileSchema> {
54 | 
55 |   name = "write_file";
56 | 
57 |   description =
58 |     "Write the entire file content. " +
59 |     "IMPORTANT: For the content parameter, provide the raw file content directly as a plain string. " +
60 |     "Do NOT wrap it in markdown code blocks (```), backticks, or any other formatting. " +
61 |     "Just pass the actual file content as-is.";
62 | 
63 |   schema = writeFileSchema;
64 | 
65 |   async execute({ filePath, content }: any) {
66 |     const fullPath = path.resolve(process.cwd(), filePath);
67 | 
68 |     // 在写入前备份现有文件（如果存在）
69 |     const backupManager = getBackupManager();
70 |     await backupManager.initialize();
71 |     const backupId = await backupManager.backup(fullPath);
72 | 
73 |     fs.mkdirSync(path.dirname(fullPath), { recursive: true });
74 |     fs.writeFileSync(fullPath, content);
75 | 
76 |     const backupInfo = backupId ? ` (backup: ${backupId})` : '';
77 |     return `File ${filePath} written successfully.${backupInfo}`;
78 |   }
79 | }
